# ---------------- TEXTS ----------------
def tok(s):
    """'汉字|pīnyīn 汉字|pīn yīn ，|' → tokens. '|'-гүй, ханзгүй хэсгийг өмнөх токений пиньиньд залгана."""
    out=[]
    for t in s.split(" "):
        if not t: continue
        if "|" in t:
            z,_,py = t.partition("|"); out.append({"zh":z,"py":py})
        elif out and not re.search(r"[一-鿿]", t):
            out[-1]["py"] = (out[-1]["py"] + " " + t).strip()
        else:
            out.append({"zh":t,"py":""})
    return out

